const links=[['submit','current'],['submit','place'],['preview','total'],['place','cartget'],['place','total'],['place','charge'],['place','create'],['place','save'],['place','notify'],['total','cartget'],['cancel','find'],['cancel','refund'],['cancel','ocancel'],['cancel','save'],['clear','cartget'],['current','userfind'],['notify','send']];
const methods=new Map();classes.forEach(c=>c.methods.forEach((m,i)=>methods.set(m[0],{id:m[0],name:m[1],returns:m[2],signature:m[3],description:m[4],code:m[5],c,i})));
let showMethods=false;
let selected=null,selectedClass=null,hovered=null,board='checkout',scale=.82,tx=15,ty=12;let codeHeight=292;
const labels={checkout:'Checkout flow',identity:'Identity',notifications:'Notifications',all:'Вся архитектура'};
function visibleLinks(){if(showMethods)return links;const seen=new Set();return links.filter(([a,b])=>{const from=methods.get(a).c.id,to=methods.get(b).c.id,key=from+'>'+to;if(from===to||seen.has(key))return false;seen.add(key);return true})}
function setMethodsVisible(value){showMethods=value;hovered=null;$('#tooltip').hidden=true;const button=$('#toggle-methods');button.setAttribute('aria-pressed',String(value));button.setAttribute('aria-label',value?'Скрыть функции':'Показать функции');button.title=value?'Скрыть функции':'Показать функции';render()}
$('#toggle-methods').onclick=()=>setMethodsVisible(!showMethods);
// Prefer smooth direct curves; use the obstacle grid only when a card blocks them.
function routeConnection(a,b,index){
 const from=methods.get(a),to=methods.get(b),gap=20+(index%4)*6;
 const boxes=classes.map(c=>{const el=$('#c-'+c.id);return{id:c.id,left:c.x,top:c.y,right:c.x+el.offsetWidth,bottom:c.y+el.offsetHeight}});
 const source=boxes.find(r=>r.id===from.c.id),target=boxes.find(r=>r.id===to.c.id);
 const centerY=m=>{const card=$('#c-'+m.c.id),row=$('#m-'+m.id);return m.c.y+(showMethods?row.offsetTop+row.offsetHeight/2:card.offsetHeight/2)};
 // Vertically aligned cards use the same exterior side, never a diagonal through a card.
 const vertical=Math.abs(from.c.x-to.c.x)<272;
 const rightward=to.c.x>from.c.x;
 const sourceSide=vertical?1:(rightward?1:-1),targetSide=vertical?1:(rightward?-1:1);
 const start=[sourceSide===1?source.right:source.left,centerY(from)];
 const end=[targetSide===1?target.right:target.left,centerY(to)];
 // Check the full curve before accepting it, including the source and target cards.
 const clearCurve=(c1,c2)=>{const steps=Math.ceil((Math.abs(end[0]-start[0])+Math.abs(end[1]-start[1])+400)/3);for(let i=1;i<steps;i++){const t=i/steps,u=1-t,x=u*u*u*start[0]+3*u*u*t*c1[0]+3*u*t*t*c2[0]+t*t*t*end[0],y=u*u*u*start[1]+3*u*u*t*c1[1]+3*u*t*t*c2[1]+t*t*t*end[1];if(boxes.some(r=>x>r.left+.25&&x<r.right-.25&&y>r.top+.25&&y<r.bottom-.25))return false}return true};
 const reach=vertical?Math.min(155,65+Math.abs(end[1]-start[1])*.24):Math.max(65,Math.abs(end[0]-start[0])*.48);
 for(const bend of [reach,reach*.7,reach*1.35,60,220,340]){const c1=[start[0]+sourceSide*bend,start[1]],c2=[end[0]+targetSide*bend,end[1]];if(clearCurve(c1,c2))return `M${start.join(' ')} C${c1.join(' ')},${c2.join(' ')},${end.join(' ')}`;}
 const entry=[start[0]+sourceSide*gap,start[1]],exit=[end[0]+targetSide*gap,end[1]];
 const obstacles=boxes.map(r=>({left:r.left-gap,right:r.right+gap,top:r.top-gap,bottom:r.bottom+gap}));
 const xs=[...new Set([entry[0],exit[0],...obstacles.flatMap(r=>[r.left,r.right])])].sort((a,b)=>a-b);
 const ys=[...new Set([entry[1],exit[1],...obstacles.flatMap(r=>[r.top,r.bottom])])].sort((a,b)=>a-b);
 const blocked=(p,q)=>obstacles.some(r=>p[0]===q[0]?p[0]>r.left&&p[0]<r.right&&Math.max(p[1],q[1])>r.top&&Math.min(p[1],q[1])<r.bottom:p[1]>r.top&&p[1]<r.bottom&&Math.max(p[0],q[0])>r.left&&Math.min(p[0],q[0])<r.right);
 const width=xs.length,point=n=>[xs[n%width],ys[Math.floor(n/width)]],node=p=>ys.indexOf(p[1])*width+xs.indexOf(p[0]);
 const begin=node(entry),finish=node(exit),queue=[{n:begin,dir:0,cost:0,key:begin*2}],distance=new Map([[begin*2,0]]),previous=new Map();let last=null;
 while(queue.length){queue.sort((a,b)=>b.cost-a.cost);const current=queue.pop();if(current.cost!==distance.get(current.key))continue;if(current.n===finish){last=current.key;break}const x=current.n%width,y=Math.floor(current.n/width);
 for(const [dx,dy,dir] of [[-1,0,0],[1,0,0],[0,-1,1],[0,1,1]]){const nx=x+dx,ny=y+dy;if(nx<0||nx>=width||ny<0||ny>=ys.length)continue;const next=ny*width+nx,p=point(current.n),q=point(next);if(blocked(p,q))continue;const cost=current.cost+Math.abs(p[0]-q[0])+Math.abs(p[1]-q[1])+(dir!==current.dir?24:0),key=next*2+dir;if(cost>=(distance.get(key)??Infinity))continue;distance.set(key,cost);previous.set(key,current.key);queue.push({n:next,dir,cost,key})}}
 if(last===null)return ''; // Never fall back to a line through an obstacle.
 const points=[];for(let key=last;key!==undefined;key=previous.get(key))points.push(point(Math.floor(key/2)));points.reverse();points.unshift(start);points.push(end);
 const compact=[];for(const p of points){if(compact.length&&p[0]===compact.at(-1)[0]&&p[1]===compact.at(-1)[1])continue;while(compact.length>1){const a=compact.at(-2),b=compact.at(-1);if((a[0]===b[0]&&b[0]===p[0])||(a[1]===b[1]&&b[1]===p[1]))compact.pop();else break}compact.push(p)}
 let path='M'+compact[0].join(' ');
 for(let i=1;i<compact.length-1;i++){const prev=compact[i-1],p=compact[i],next=compact[i+1],before=Math.hypot(p[0]-prev[0],p[1]-prev[1]),after=Math.hypot(next[0]-p[0],next[1]-p[1]),radius=Math.min(gap-3,before/2,after/2);const enter=[p[0]+(prev[0]-p[0])*radius/before,p[1]+(prev[1]-p[1])*radius/before],leave=[p[0]+(next[0]-p[0])*radius/after,p[1]+(next[1]-p[1])*radius/after];path+=` L${enter.join(' ')} Q${p.join(' ')} ${leave.join(' ')}`;}
 return path+' L'+compact.at(-1).join(' ');
}
function render(){document.querySelector('#world').classList.toggle('classes-only',!showMethods);let html=`<div class="cluster" style="left:35px;top:45px;width:1125px;height:745px"><div class="cluster-label">CHECKOUT FLOW <small>6 классов · 2 новых</small></div></div><div class="cluster" style="left:1300px;top:45px;width:770px;height:310px;border-color:#314856"><div class="cluster-label">IDENTITY <small>2 класса</small></div></div><div class="cluster" style="left:1300px;top:495px;width:770px;height:310px;border-color:#315046"><div class="cluster-label">NOTIFICATIONS <small>2 класса</small></div></div>`;
for(const c of classes)html+=`<article class="card" id="c-${c.id}" style="left:${c.x}px;top:${c.y}px"><div class="card-head" tabindex="0" role="button" data-class="${c.id}"><span class="class-icon">C</span><span class="class-title">${c.name.replace(/([a-z])([A-Z])/g,'$1<wbr>$2')}</span><span class="tag ${c.status}">${{new:'NEW',changed:'MOD',existing:'↗'}[c.status]}</span></div><div class="card-sub"><span>${c.group} / ${c.name}.cs</span><span>${c.lines} строк</span></div>${c.methods.map(m=>`<button class="method" id="m-${m[0]}" data-method="${m[0]}"><span class="fn">ƒ</span>${m[1]}<span class="return">${esc(m[2])}</span></button>`).join('')}<div class="card-foot">${c.methods.length} метода <span style="float:right">${c.status==='new'?'Предложен':c.status==='changed'?'Изменён':'В проекте'}</span></div></article>`;
$('#cards').innerHTML=html;
$('#edges').innerHTML=`<defs>${[['base','#596077'],['in','#65b9ef'],['out','#a9a1ff']].map(([id,color])=>`<marker id="arrow-${id}" markerWidth="6" markerHeight="6" refX="5.5" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="${color}"/></marker>`).join('')}</defs>`+visibleLinks().map(([a,b],index)=>`<path class="edge" data-a="${a}" data-b="${b}" d="${routeConnection(a,b,index)}" marker-end="url(#arrow-base)"/>`).join('');
for(const el of document.querySelectorAll('[data-method]')){el.onclick=()=>selectMethod(el.dataset.method);el.onmouseenter=e=>{hovered=el.dataset.method;highlight();showTooltip(hovered,e)};el.onmousemove=positionTooltip;el.onmouseleave=()=>{hovered=null;$('#tooltip').hidden=true;highlight()};el.onfocus=()=>{hovered=el.dataset.method;highlight()};el.onblur=()=>{hovered=null;highlight()};}
for(const el of document.querySelectorAll('[data-class]')){el.onclick=()=>selectClass(el.dataset.class);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectClass(el.dataset.class)}}}highlight();}
function highlight(){
 const methodId=showMethods?(hovered||selected):null;
 const classId=methodId?null:(selectedClass||(selected?methods.get(selected).c.id:null));
 const activeClass=methodId?methods.get(methodId).c.id:classId;
 const active=!!activeClass,relevant=new Set(activeClass?[activeClass]:[]),incoming=new Set(),outgoing=new Set();
 const direction=(a,b)=>{if(methodId)return a===methodId?'out':b===methodId?'in':'';if(classId){const from=methods.get(a).c.id,to=methods.get(b).c.id;if(from===to)return '';return from===classId?'out':to===classId?'in':''}return ''};
 for(const [a,b] of links){const type=direction(a,b);if(type==='out'){outgoing.add(b);relevant.add(methods.get(b).c.id)}if(type==='in'){incoming.add(a);relevant.add(methods.get(a).c.id)}}
 document.querySelectorAll('.card').forEach(el=>{el.classList.toggle('dim',active&&!relevant.has(el.id.slice(2)));el.classList.toggle('selected',activeClass===el.id.slice(2))});
 document.querySelectorAll('.method').forEach(el=>{const mid=el.dataset.method;el.classList.toggle('focused',mid===methodId);el.classList.toggle('in',incoming.has(mid));el.classList.toggle('out',outgoing.has(mid))});
 document.querySelectorAll('.edge').forEach(el=>{const type=direction(el.dataset.a,el.dataset.b);el.setAttribute('class','edge '+(type||(active?'dim':'')));el.setAttribute('marker-end',`url(#arrow-${type||'base'})`)});
}

function showTooltip(id,e){const m=methods.get(id);$('#tooltip').innerHTML=`<code>${esc(m.returns+' '+m.signature)}</code><div style="margin-top:8px;color:#b6bbca">${esc(m.description)}</div><pre>${esc(m.code)}</pre><div style="color:#9790b5;margin-top:8px">Нажмите, чтобы открыть полный код ↓</div>`;$('#tooltip').hidden=false;positionTooltip(e)}
function positionTooltip(e){const tip=$('#tooltip');tip.style.left=Math.max(8,Math.min(e.clientX+16,window.innerWidth-tip.offsetWidth-12))+'px';tip.style.top=Math.max(8,Math.min(e.clientY+20,window.innerHeight-tip.offsetHeight-12))+'px'}
function syntax(code){return esc(code).replace(/\b(public|private|readonly|async|await|return|var|new|static|void|if|string|decimal)\b/g,'<span class="kw">$1</span>')}
function showCode(code){$('#code').innerHTML=code.split('\n').map((l,i)=>`<span class="code-row"><span class="ln">${i+1}</span><span class="src">${syntax(l)||' '}</span></span>`).join('');$('#code').dataset.raw=code;$('#inspector').hidden=false;$('#splitter').hidden=false;$('#inspector').style.height=codeHeight+'px'}
function fillLinks(container,ids){$(container).innerHTML=ids.length?ids.map(id=>{const m=methods.get(id);return `<button class="link-method" data-jump="${id}">${m.c.name}.${m.name} ↗</button>`}).join(''):'<div class="empty">Нет в демомодели</div>';$(container).querySelectorAll('button').forEach(b=>b.onclick=()=>{selectMethod(b.dataset.jump);centerClass(methods.get(b.dataset.jump).c)})}
function selectMethod(id){if(!methods.has(id))throw new Error('Unknown method');if(!showMethods)setMethodsVisible(true);selected=id;selectedClass=null;hovered=null;$('#tooltip').hidden=true;const m=methods.get(id);$('#method-name').textContent=m.name+'()';$('#file-name').textContent=m.c.name+'.cs';$('#signature').textContent=m.returns+' '+m.signature;$('#description').textContent=m.description;showCode(m.code);fillLinks('#callers',links.filter(l=>l[1]===id).map(l=>l[0]));fillLinks('#callees',links.filter(l=>l[0]===id).map(l=>l[1]));$('#selection-status').textContent=m.c.name+' → '+m.name+' · '+m.code.split('\n').length+' строк метода';highlight();}
function selectClass(id){const c=classes.find(c=>c.id===id);selected=null;selectedClass=id;hovered=null;$('#tooltip').hidden=true;$('#method-name').textContent=c.name;$('#file-name').textContent=c.name+'.cs';$('#signature').textContent='public class '+c.name;$('#description').textContent='Поля и сигнатуры класса. Для полного тела метода выберите его в карточке.';showCode(`public class ${c.name}\n{\n${c.fields.split('\n').map(s=>'    '+s).join('\n')}\n\n${c.methods.map(m=>'    public '+m[2]+' '+m[3]+';').join('\n')}\n}`);$('#callers').innerHTML='';$('#callees').innerHTML='';$('#selection-status').textContent=c.name+' · '+c.lines+' строк файла (демо)';highlight()}
function transform(){$('#world').style.transform=`translate(${tx}px,${ty}px) scale(${scale})`;$('#scale').textContent=Math.round(scale*100)+'%'}
function fit(which=board){const v=$('#viewport');const bounds=which==='all'?[35,45,2050,765]:which==='checkout'?[35,45,1125,745]:which==='identity'?[1300,45,770,310]:[1300,495,770,310];scale=Math.max(.25,Math.min(1.1,(v.clientWidth-60)/bounds[2],(v.clientHeight-110)/bounds[3]));tx=(v.clientWidth-bounds[2]*scale)/2-bounds[0]*scale;ty=75-bounds[1]*scale;transform()}
function setBoard(value){board=value;$('#board-title').textContent=labels[value];document.querySelectorAll('.nav').forEach(b=>{const active=b.dataset.board===value||(b.id==='all'&&value==='all');b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','true');else b.removeAttribute('aria-current')});$('#board-menu').open=false;fit(value)}

function centerClass(c){const v=$('#viewport');tx=v.clientWidth/2-(c.x+136)*scale;ty=v.clientHeight/2-(c.y+100)*scale;transform()}
function zoom(f,x=$('#viewport').clientWidth/2,y=$('#viewport').clientHeight/2){const ns=Math.min(1.8,Math.max(.25,scale*f));tx=x-(x-tx)*ns/scale;ty=y-(y-ty)*ns/scale;scale=ns;transform()}
$('#plus').onclick=()=>zoom(1.2);$('#minus').onclick=()=>zoom(1/1.2);$('#fit').onclick=()=>fit();$('#overview').onclick=()=>setBoard('all');$('#all').onclick=()=>setBoard('all');document.querySelectorAll('[data-board]').forEach(b=>b.onclick=()=>setBoard(b.dataset.board));$('#close').onclick=()=>{$('#inspector').hidden=true;$('#splitter').hidden=true};$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#code').dataset.raw);$('#copy').textContent='Скопировано';setTimeout(()=>$('#copy').textContent='Копировать',1400)}catch{$('#copy').textContent='Выделите код вручную'}};
const viewport=$('#viewport');let drag=null;viewport.onpointerdown=e=>{if(e.target.closest('button,.card,#tooltip'))return;drag={x:e.clientX,y:e.clientY,tx,ty,moved:false};viewport.setPointerCapture(e.pointerId);viewport.classList.add('dragging');$('#tooltip').hidden=true};viewport.onpointermove=e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>5)drag.moved=true;tx=drag.tx+e.clientX-drag.x;ty=drag.ty+e.clientY-drag.y;transform()};viewport.onpointerup=e=>{if(drag&&!drag.moved&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)<=5){selected=null;selectedClass=null;hovered=null;$('#tooltip').hidden=true;highlight()}drag=null;viewport.classList.remove('dragging')};viewport.onpointercancel=()=>{drag=null;viewport.classList.remove('dragging')};viewport.addEventListener('wheel',e=>{e.preventDefault();if(e.ctrlKey||e.metaKey){const r=viewport.getBoundingClientRect();zoom(e.deltaY<0?1.08:1/1.08,e.clientX-r.left,e.clientY-r.top)}else{tx-=e.deltaX;ty-=e.deltaY;transform()}},{passive:false});viewport.onkeydown=e=>{if(e.target!==viewport)return;const move={ArrowUp:[0,40],ArrowDown:[0,-40],ArrowLeft:[40,0],ArrowRight:[-40,0]}[e.key];if(move){e.preventDefault();tx+=move[0];ty+=move[1];transform()}if(e.key==='Escape'){selected=null;selectedClass=null;hovered=null;highlight()}if(e.key==='+')zoom(1.2);if(e.key==='-')zoom(1/1.2)};
let resizeStart=null;const splitter=$('#splitter');splitter.onpointerdown=e=>{resizeStart={y:e.clientY,height:$('#inspector').offsetHeight};splitter.setPointerCapture(e.pointerId)};splitter.onpointermove=e=>{if(!resizeStart)return;codeHeight=Math.max(130,Math.min(innerHeight*.65,resizeStart.height+resizeStart.y-e.clientY));$('#inspector').style.height=codeHeight+'px'};splitter.onpointerup=()=>resizeStart=null;splitter.onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();codeHeight=Math.max(130,Math.min(innerHeight*.65,codeHeight+(e.key==='ArrowUp'?20:-20)));$('#inspector').style.height=codeHeight+'px'}};
render();requestAnimationFrame(()=>fit());
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#board-menu'))$('#board-menu').open=false});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#board-menu').open){$('#board-menu').open=false;$('#board-menu summary').focus()}});

if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'inspect_method',title:'Открыть метод',description:'Select a method in the demo architecture and display its code and direct callers.',inputSchema:{type:'object',properties:{methodId:{type:'string',enum:[...methods.keys()]}},required:['methodId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!methods.has(input.methodId))throw new Error('Unknown method');selectMethod(input.methodId);centerClass(methods.get(input.methodId).c);return{selectedMethod:input.methodId,code:methods.get(input.methodId).code}}})).catch(()=>{})}catch{}}
